<?php
declare(strict_types=1);requireRole($user,['provincial_admin']);
$editId=(int)($_GET['edit_unit'] ?? 0);$deleteId=(int)($_GET['delete_unit'] ?? 0);$editing=null;$deleting=null;
foreach($nodes as $unit){if((int)$unit['id']===$editId)$editing=$unit;if((int)$unit['id']===$deleteId)$deleting=$unit;}
?>
<section class="panel form-panel unit-editor" id="hierarchy-editor" tabindex="-1" aria-labelledby="unit-editor-title">
 <div class="section-kicker"><?= $editing?'EDIT CHURCH UNIT':'QUICK ADD' ?></div>
 <div class="editor-heading"><h2 id="unit-editor-title"><?= $editing?'Update church details':'Add a church unit' ?></h2><?php if($editing): ?><a class="text-link" href="?page=hierarchy#hierarchy-editor">＋ Add new instead</a><?php endif ?></div>
 <p class="muted"><?= $editing?'Update details or the parent while keeping this unit’s ID, accounts and reports. Unit level cannot be changed here.':'Start with a Zone, add its Areas, then its Parishes. A new Parish can also belong directly to a Zone.' ?></p>
 <?php if($editId && !$editing): ?><div class="alert">The selected unit is unavailable. Choose a unit from the directory.</div><?php endif ?>
 <?php if($editing && !empty($error)): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif ?>
 <form method="post" action="?page=hierarchy<?= $editing?'&amp;edit_unit='.(int)$editing['id']:'' ?>#hierarchy-editor" class="form-grid">
  <?php hiddenAction($editing?'edit_unit':'node') ?>
  <?php if($editing): ?><input type="hidden" name="unit_id" value="<?= (int)$editing['id'] ?>"><?php endif ?>
  <label class="full-width">Unit name<input name="node_name" value="<?= e($editing['node_name'] ?? '') ?>" maxlength="150" required placeholder="e.g. Living Hope Parish"></label>
  <?php if($editing): ?><label>Unit level<input value="<?= e(ucfirst($editing['node_type'])) ?>" readonly><input type="hidden" name="node_type" value="<?= e($editing['node_type']) ?>"></label><?php else: ?><label>Unit level<select name="node_type"><option value="zone">Zone</option><option value="area">Area</option><option value="parish">Parish</option></select></label><?php endif ?>
  <label>Parish code (parishes only)<input name="parish_code" value="<?= e($editing['parish_code'] ?? '') ?>" maxlength="20" placeholder="e.g. LHP001"></label>
  <?php if(!$editing || $editing['node_type']!=='zone'): ?><label class="full-width">Parent zone or area (not used for zones)<select name="parent_id" data-unit-search><option value="0">Provincial treasury / no parent for Zones</option><?php foreach($nodes as $parent):if($parent['node_type']==='parish' || ($editing && (int)$parent['id']===(int)$editing['id']) || ($editing && $editing['node_type']==='area' && $parent['node_type']!=='zone'))continue; ?><option value="<?= (int)$parent['id'] ?>" <?= $editing && (int)$editing['parent_id']===(int)$parent['id']?'selected':'' ?>><?= e(unitLabel($parent)) ?></option><?php endforeach ?></select></label><?php endif ?>
  <label>Contact person<input name="contact_person" value="<?= e($editing['contact_person'] ?? '') ?>" maxlength="100"></label><label>Contact phone<input type="tel" name="phone_number" value="<?= e($editing['phone_number'] ?? '') ?>" maxlength="25"></label>
  <div class="editor-buttons full-width"><button class="primary"><?= $editing?'Save church changes':'Add church unit →' ?></button><?php if($editing): ?><a class="secondary" href="?page=hierarchy#church-directory">Cancel edit</a><?php endif ?></div>
 </form>
</section>
<?php if($deleting): ?><section class="panel form-panel danger-panel" id="delete-unit" tabindex="-1" aria-labelledby="delete-unit-title"><div class="section-kicker">CONFIRM DELETION</div><h2 id="delete-unit-title">Delete <?= e($deleting['node_name']) ?>?</h2><p>This permanently removes this unit only if it has no child churches, officer accounts, registrations or financial records. Move child units first. Historical data will never be deleted by this tool.</p><?php if(!empty($error)): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" action="?page=hierarchy&amp;delete_unit=<?= (int)$deleting['id'] ?>#delete-unit"><?php hiddenAction('delete_unit') ?><input type="hidden" name="unit_id" value="<?= (int)$deleting['id'] ?>"><label>Type the exact unit name<input name="confirm_name" required autocomplete="off" placeholder="<?= e($deleting['node_name']) ?>"></label><label class="check-label"><input type="checkbox" name="delete_confirm" value="1" required><span>I understand that this unused unit will be permanently deleted.</span></label><div class="editor-buttons"><button class="danger-button">Delete unused unit</button><a class="secondary" href="?page=hierarchy#church-directory">Cancel</a></div></form></section><?php elseif($deleteId): ?><div class="notice">The selected unit is unavailable or has already been removed.</div><?php endif ?>
